contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address recipient) public payable {
        require(c.owner() == address(this), "test must be owner");
        require(recipient == address(this), "recipient must accept ETH");
        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && address(c).balance == 0);
    }
    receive() external payable {}
}

